@Immutable
data class FeedUiState(
    val items: ImmutableList<Item> = persistentListOf(),
    val isRefreshing: Boolean = false,
    val error: ErrorMessage? = null,
)

sealed interface FeedAction {
    data object Refresh : FeedAction
    data class Select(val id: String) : FeedAction
    data class Dismiss(val errorId: Long) : FeedAction
}

@HiltViewModel
class FeedViewModel @Inject constructor(
    private val observeFeed: ObserveFeedUseCase,
    private val refreshFeed: RefreshFeedUseCase,
) : ViewModel() {

    private val _state = MutableStateFlow(FeedUiState())
    val state: StateFlow<FeedUiState> = _state.asStateFlow()

    init {
        observeFeed()
            .onEach { items -> _state.update { it.copy(items = items.toImmutableList()) } }
            .launchIn(viewModelScope)
    }

    fun onAction(action: FeedAction) = when (action) {
        FeedAction.Refresh   -> refresh()
        is FeedAction.Select -> { /* navigate */ }
        is FeedAction.Dismiss -> _state.update { it.copy(error = null) }
    }
}

