@Entity
data class NoteEntity(
    @PrimaryKey val id: String,          // client-generated UUID until the server assigns one
    val serverId: String? = null,
    val text: String,
    val updatedAt: Long,
    val pendingSync: Boolean = false,
    val syncFailed: Boolean = false,
)

class NoteRepository(
    private val dao: NoteDao,
    private val api: NoteApi,
    private val workManager: WorkManager,
) {
    // Reads always come from the database
    fun observe(): Flow<List<Note>> = dao.observeAll().map { it.map(NoteEntity::toDomain) }

    // Writes are local-first and optimistic
    suspend fun save(text: String) {
        dao.upsert(
            NoteEntity(
                id = UUID.randomUUID().toString(),
                text = text,
                updatedAt = System.currentTimeMillis(),
                pendingSync = true,
            )
        )
        workManager.enqueueUniqueWork(
            "outbox", ExistingWorkPolicy.KEEP,
            OneTimeWorkRequestBuilder<OutboxWorker>()
                .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
                .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
                .build()
        )
    }
}

